			{(8-NETDEVS){1'b0}}, r_netlock_los,
			{(8-NETDEVS-1){1'b0}}, r_netlock_phy_locked };

	always @(posedge i_clk)
	begin
		r_netlock_los        <= i_gnet_los;
		r_netlock_phy_locked <= i_gnet_phy_locked;
	end
`ifdef	SATATSCOPE_SCOPC
