		.i_wb_cyc(wb32_satatscope_cyc), .i_wb_stb(wb32_satatscope_stb), .i_wb_we(wb32_satatscope_we),
			.i_wb_addr(wb32_satatscope_addr[1-1:0]),
			.i_wb_data(wb32_satatscope_data), // 32 bits wide
			.i_wb_sel(wb32_satatscope_sel),  // 32/8 bits wide
		.o_wb_stall(wb32_satatscope_stall),.o_wb_ack(wb32_satatscope_ack), .o_wb_data(wb32_satatscope_idata),
		.o_interrupt(satatscope_int)
