	// responding on the wb32 bus
	assign	wb32_satatscope_ack   = 1'b0;
	assign	wb32_satatscope_err   = (wb32_satatscope_stb);
	assign	wb32_satatscope_stall = 0;
	assign	wb32_satatscope_idata = 0;

	// }}}
